def parse_ref_abbr(block: 'BlockParser', m: Match[str], state: 'BlockState'
    ) ->int:
    abbr_key = m.group('abbr_key')
    abbr_text = m.group('abbr_text').strip()

    if 'abbr' not in state.env:
        state.env['abbr'] = {}

    state.env['abbr'][abbr_key] = abbr_text
    return m.end()


def process_text(inline: 'InlineParser', text: str, state: 'InlineState'
    ) ->None:
    abbr_dict = state.env.get('abbr', {})
    if not abbr_dict:
        state.append_token({'type': 'text', 'raw': text})
        return

    pattern = '|'.join(re.escape(key) for key in sorted(abbr_dict.keys(), key=len, reverse=True))
    if not pattern:
        state.append_token({'type': 'text', 'raw': text})
        return

    regex = re.compile(f'({pattern})')
    parts = regex.split(text)

    for part in parts:
        if not part:
            continue
        if part in abbr_dict:
            state.append_token({
                'type': 'abbr',
                'raw': part,
                'title': abbr_dict[part]
            })
        else:
            state.append_token({'type': 'text', 'raw': part})


def abbr(md: 'Markdown') ->None:
    md.block.register(
        'ref_abbr',
        REF_ABBR,
        parse_ref_abbr,
        before='ref_link'
    )

    if md.renderer and hasattr(md.renderer, 'abbr'):
        pass
    else:
        md.renderer.abbr = types.MethodType(render_abbr, md.renderer)

    md.inline.register('text', process_text, before='escape')
